/** 编译预览抽屉。 */
export function PlanDrawer(props: {
  t: Translate
  plan: { text: string; blocked: boolean; id: string } | null
  tab: 'dispatch' | 'full'
  onTab: (tab: 'dispatch' | 'full') => void
  open: boolean
  onOpen: (open: boolean) => void
}): React.JSX.Element {
  const { t, plan } = props
  const [copied, setCopied] = useState(false)
  useEffect(() => {
    if (!copied) return
    const timer = setTimeout(() => setCopied(false), 1600)
    return () => clearTimeout(timer)
  }, [copied])

  /** 导出 = 触发浏览器下载，插件自己不写盘（§9）。只给整卷版。 */
  const exportFull = (): void => {
    if (plan === null || plan.blocked) return
    const blob = new Blob([plan.text], { type: 'text/markdown;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `workflow-plan-${plan.id === '' ? 'latest' : plan.id}.md`
    link.click()
    // 撤销要等浏览器真的把下载接过去；同步撤销会掐断下载。
    setTimeout(() => URL.revokeObjectURL(url), 0)
  }

  return (
    <section className={[css.drawer, props.open ? css.drawerOpen : ''].join(' ')}>
      <div className={css.drawerHead}>
        <span className={css.label}>{t('plan.title')}</span>
        <div className={css.tabs}>
          <button
            type="button"
            className={props.tab === 'dispatch' ? css.tabActive : css.tab}
            onClick={() => props.onTab('dispatch')}
          >
            {t('plan.dispatch')}
          </button>
          <button
            type="button"
            className={props.tab === 'full' ? css.tabActive : css.tab}
            onClick={() => props.onTab('full')}
          >
            {t('plan.full')}
          </button>
        </div>
        <span className={css.barSpacer} />
        {plan !== null && !plan.blocked && (
          <>
            {plan.id !== '' && (
              <span className={css.status}>
                {t('plan.planId')} {plan.id}
              </span>
            )}
            <button
              type="button"
              className={css.button}
              onClick={() => {
                void navigator.clipboard.writeText(plan.text).then(() => setCopied(true))
              }}
            >
              {copied ? t('plan.copied') : t('plan.copy')}
            </button>
            {props.tab === 'full' && (
              <button type="button" className={css.button} onClick={exportFull}>
                {t('plan.export')}
              </button>
            )}
          </>
        )}
        <button
          type="button"
          className={css.button}
          onClick={() => props.onOpen(!props.open)}
        >
          {props.open ? t('plan.collapse') : t('plan.expand')}
        </button>
      </div>
      {props.open && (
        <div className={css.drawerBody}>
          {plan === null ? (
            <p className={css.muted}>{t('plan.empty')}</p>
          ) : plan.blocked ? (
            <p className={css.problem}>{t('plan.blocked')}</p>
          ) : (
            <pre className={css.plan}>{plan.text}</pre>
          )}
        </div>
      )}
    </section>
  )
}

