/// Swap the live session's expert binding and re-arm the first-message
/// prelude (office expert switch on the gateway/ACP path).
///
/// `AcpSessionParams` is frozen at build time and `set_expert` builds the
/// agent task before it saves the new binding, so the params always
/// describe the expert the user just left. Overriding the binding on the
/// session aggregate is what makes the incoming expert's `[Assistant
/// Rules]` / skills index reach the next prompt; the task handle itself is
/// reused, so this never fails the switch.
///
/// Covers a clear too: the caller passes the post-clear `extra` values, so
/// the baseline is re-injected rather than the outgoing expert's rules.
pub(super) async fn apply_expert_binding(&self, preset_context: Option<String>, skills: Vec<String>) {
    let mut session = self.session.write().await;
    session.apply_expert_binding(preset_context, skills);
}

