/**
 * 第三方声明不许漂移。
 *
 * `lib/client.js` 是**内联**打包的：第三方代码的字节进了我们的发布物，就得逐条声明。
 * 内联了新的包而 `THIRD_PARTY_NOTICES.md` 没跟着补，是那种"谁都不会注意到"的漏——
 * 直到有人来问许可证。这里拿构建产物的 source map 当事实来源，两个方向都比一遍。
 * 同样需要构建产物，没构建过就跳过。
 */
describe.skipIf(!existsSync(fileURLToPath(new URL('../lib/client.js.map', import.meta.url))))(
  '第三方声明',
  () => {
    /** 从 source map 反查真正被内联进来的包（pnpm 的 `.pnpm/<name>@<ver>/node_modules/<name>/`）。 */
    const inlined = (): Set<string> => {
      const map = JSON.parse(read('lib/client.js.map')) as { sources?: string[] }
      const names = new Set<string>()
      for (const source of map.sources ?? []) {
        const match = /node_modules\/\.pnpm\/(.+?)@([0-9][^/]*)\/node_modules\/((?:@[^/]+\/)?[^/]+)\//u.exec(
          source,
        )
        if (match !== null) names.add(match[3] as string)
      }
      return names
    }

    /** `THIRD_PARTY_NOTICES.md` 的「内联清单」表里列出的包。 */
    const declared = (): Set<string> => {
      const names = new Set<string>()
      for (const line of read('THIRD_PARTY_NOTICES.md').split('\n')) {
        const match = /^\|\s*`([^`]+)`\s*\|/u.exec(line)
        if (match !== null) names.add(match[1] as string)
      }
      return names
    }

    it('source map 认出来的包都有名字，不是空表', () => {
      expect(inlined().size).toBeGreaterThan(3)
    })

    it('内联进来的都声明了', () => {
      const missing = [...inlined()].filter((name) => !declared().has(name))
      expect(missing, '这些包被内联进 lib/client.js，却没有在 THIRD_PARTY_NOTICES.md 里声明').toEqual(
        [],
      )
    })

    it('声明过的都还在内联（不会留下删不掉的旧条目）', () => {
      const stale = [...declared()].filter((name) => !inlined().has(name))
      expect(stale, '这些包已经不被内联了，声明里却还留着').toEqual([])
    })
  },
)

