 * 都能在声明里找到出处。②兜的是生成器看不见的东西——比如某个依赖在自己的预打包产物里
 * 又 vendored 了一支代码（`web-worker` 就是这么冒出来的），源码地图对它一无所知。
 * 同样需要构建产物，没构建过就跳过。
 */
describe.skipIf(!existsSync(fileURLToPath(new URL('../lib/client.js.map', import.meta.url))))(
  '第三方声明',
  () => {
    it('与生成器现在的输出逐字一致', async () => {
      const { renderNotices } = await import('../scripts/notices.mjs')
      expect(read('THIRD_PARTY_NOTICES.md')).toBe(renderNotices())
    })

    it('产物里每一条版权行都能在声明里找到出处', async () => {
      const { copyrightLines } = await import('../scripts/notices.mjs')
      const notices = read('THIRD_PARTY_NOTICES.md')
      const lines = copyrightLines()
      expect(lines.length, '一条版权行都没扫到，说明扫描规则失效了').toBeGreaterThan(0)
      const missing = lines.filter((line) => !notices.includes(line))
      expect(missing, '这些版权行出现在产物里，声明里却没有').toEqual([])
    })
  },
)

