    const body = '{"url":"https://im.example/sso?ticket=T-123","success":true}';
    const out = sanitizeBody(body);
    expect(out).not.toContain('T-123');
    expect(out).toContain('ticket=<redacted>');
    expect(out).toContain('"success":true');
  });

  it('把 JSON 里的 accessToken / account_id / secret 抹掉', () => {
    const out = sanitizeBody(
      '{"accessToken":"AT-1","account_id":"ACCT-1","secret":"S-1","jobNo":"15295"}',
    );
    expect(out).not.toContain('AT-1');
    expect(out).not.toContain('ACCT-1');
    expect(out).not.toContain('S-1');
    expect(out).toContain('"accessToken":"<redacted>"');
    expect(out).toContain('"account_id":"<redacted>"');
    // 工号不是凭证，要留着和 OA 侧日志对账。
    expect(out).toContain('15295');
  });

  it('未加引号的值也盖得住', () => {
    const out = sanitizeBody('{"accessToken":123456}');
    expect(out).not.toContain('123456');
