    assert!(inspected.skills[0].conflict.is_none());
    assert_eq!(inspected.skills[0].default_action, BundleImportAction::Copy);
    assert_eq!(inspected.skills[0].import_name.as_deref(), Some("demo-skill"));

    let applied = fx
        .bundle
        .apply(
            ApplyBundleRequest {
                bundle_id: inspected.bundle_id,
                assistants: vec![BundleDecisionRequest {
                    key: "exported-expert".to_string(),
                    action: BundleImportAction::Copy,
                }],
                mcp_servers: Vec::new(),
                skills: vec![BundleDecisionRequest {
                    key: "Demo_Skill".to_string(),
                    action: BundleImportAction::Copy,
                }],
            },
            TEST_OWNER,
        )
        .await
        .unwrap();

    assert_eq!(applied.skills[0].name.as_deref(), Some("demo-skill"));
    let skill_manifest = fx.skill_paths.user_skills_dir.join("demo-skill/SKILL.md");
    let body = std::fs::read_to_string(&skill_manifest).unwrap();
    assert!(body.contains("name: demo-skill"));
    assert!(!fx.skill_paths.user_skills_dir.join("Demo_Skill").exists());

    let new_assistant_id = applied.assistants[0].id.clone().unwrap();
    let detail = fx.assistant.get_detail(&new_assistant_id, Some("zh-CN")).await.unwrap();
    assert_eq!(detail.defaults.skills.value, vec!["demo-skill".to_string()]);
}

