async #answerPermission(pending: Pending & { kind: "permission" }, text: string): Promise<boolean> {
	const reply = parsePermissionReply(text);
	if (!reply) {
		// Never guess at an approval: repeat the menu and do not consume the message
		// as a prompt either (that would silently lose it mid-decision).
		await this.#deps.send("没看懂。回复 1（批准一次）、 2（本会话不再询问）或 3（拒绝）。");
		return true;
	}
	this.#clear();
	await this.#invoke(pending.sessionId, "permission", {
		action: "confirm",
		requestId: pending.requestId,
		approved: reply.approved,
		remember: reply.remember,
	});
	await this.#deps.send(
		reply.approved
			? reply.remember
				? `已批准，本会话内不再询问「${pending.toolName}」。`
				: "已批准执行。"
			: "已拒绝执行。",
	);
	return true;
}

