async #stopPolling(): Promise<void> {
	this.#unsubscribeGatewayEvents();
	if (this.#heartbeat) {
		clearInterval(this.#heartbeat);
		this.#heartbeat = null;
	}
	const abort = this.#pollAbort;
	this.#pollAbort = null;
	const task = this.#pollTask;
	this.#pollTask = null;
	if (task) await task.catch(() => undefined);

	const credentials = await this.#store.loadCredentials();
	await this.#stopTyping(credentials);
	if (credentials) {
		try {
			await this.#api.notifyStop({ baseUrl: credentials.baseUrl, token: credentials.token });
		} catch (error) {
			log.warn("WeChat notifyStop failed", { error: describeError(error) });
		}
	}

newText:
async #stopPolling(): Promise<void> {
	const wasRunning = this.#pollTask !== null || this.#pollAbort !== null;
	this.#unsubscribeGatewayEvents();
	if (this.#heartbeat) {
		clearInterval(this.#heartbeat);
		this.#heartbeat = null;
	}
	const abort = this.#pollAbort;
	this.#pollAbort = null;
	const task = this.#pollTask;
	this.#pollTask = null;
	if (task) await task.catch(() => undefined);

	const credentials = await this.#store.loadCredentials();
	await this.#stopTyping(credentials);
	if (credentials && wasRunning) {
		try {
			await this.#api.notifyStop({ baseUrl: credentials.baseUrl, token: credentials.token });
		} catch (error) {
			log.warn("WeChat notifyStop failed", { error: describeError(error) });
		}
	}

